const u8 *RomPtr(u8 bank, u16 address)
{
	for (int i = 0; i < NUM_ROM_BLOBS; i++) {
		const struct RomBlob *b = &gRomBlobs[i];
		if (b->bank == bank && address >= b->address && address < b->address + b->size)
			return b->data + (address - b->address);
	}
	return 0;
}

u16 RomAddr(const char *label)
{
	for (int i = 0; i < NUM_ROM_BLOBS; i++)
		if (!strcmp(gRomBlobs[i].label, label))
			return gRomBlobs[i].address;
	return 0;
}
